// BANK-STEPS-1 (2026-10-13) - the LEDGER for the lane that repairs spliced worked solutions. One entry per row whose `solutionSteps` answer a DIFFERENT
// question than the row's own stem (found by BANK-STEPS-SCOUT, #973 comment 6141462325; each verdict read by a fresh-context Opus judge, with one sentence of evidence).
// Generated from the scout CSV by script - the ids are never typed by hand. States: "paused" (in the BANK-STEPS-1 PAUSE block of WITHHELD_QUESTION_IDS),
// "found" (FIND hit, still served: e.g. NO-ANSWER rows), "paused" (in the PAUSE block), "repaired" (new steps written, re-solve agreed, id removed from the block) or "dropped" (cannot be repaired: moved to the UNREPAIRABLE block with a reason). A row's state only moves forward (D143).
// Row ids, questionText and options are never changed by this lane. answer/finalAnswer only change by cofounder ruling on the board (D170: the keys of CR-M04 and ABS-E06 became option (b); D207: the key of CNC2-041 became NCERT's fore-/mid-/hind-brain, and sci-chem-acids-2m-2022-01 got its key from the universal indicator chart (D223 fallback, no pH band); D232/D238: EL-E14's formative-only distractors 'Electric motor' and 'Generator' became 'Electromagnet' and 'Electric bell', key unchanged; each noted on its ledger row); D228: SINGLE-STEP rows' answer/finalAnswer de-flattened.

export type BankSteps1State = "found" | "paused" | "repaired" | "dropped";

export interface BankSteps1Entry {
  id: string;
  /** Pack file under src/data/questionBanks/ that holds the row. */
  file: string;
  verdict: "MISPAIRED" | "PARTIAL" | "NO-ANSWER" | "OVER-PAUSED" | "SINGLE-STEP" | "WRONG-CONTENT" | "TEXT-FAULT";
  /** One sentence from the independent judge: what the stem asks vs what the steps do. */
  evidence: string;
  /** The row whose question the stored steps actually answer, when the judge could name it. */
  likelyTrueOwnerId: string | null;
  state: BankSteps1State;
}

